// ─── STRIPE CHECKOUT ──────────────────────────────────────────────────────────
// Calls our Netlify serverless function which creates a Stripe checkout session
async function goToCheckout(priceId, email) {
  const mode = priceId === PRICES.day ? "payment" : "subscription";
  
  const res = await fetch("/.netlify/functions/create-checkout", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ priceId, mode, customerEmail: email || null }),
  });

  if (!res.ok) {
    const err = await res.json();
    throw new Error(err.error || "Checkout failed");
  }

  const { url } = await res.json();
  window.location.href = url; // Redirect to Stripe hosted checkout page
}

// ─── WEATHER / SCORING ────────────────────────────────────────────────────────
function analyzePressure(readings){
  if(!readings||readings.length<3)return null;
  const delta=readings[readings.length-1]-readings[0];
  if(delta>1.5) return{trend:"RISING",        arrow:"↑",color:"#6abf69",scentRating:9.5,label:"Excellent Scenting",detail:"Pressure rising — rabbits are active and moving. Your dogs will smell them with ease. Get out now."};
  if(delta>0.5) return{trend:"RISING SLOWLY", arrow:"↗",color:"#a0d080",scentRating:8.0,label:"Good Scenting",     detail:"Pressure creeping up — scent carrying well near the ground. Good day for your dogs."};
  if(delta>-0.5)return{trend:"STEADY",        arrow:"→",color:"#f5a623",scentRating:6.5,label:"Fair Scenting",     detail:"Pressure holding steady — average scenting conditions."};
  if(delta>-1.5)return{trend:"FALLING",       arrow:"↘",color:"#e07020",scentRating:4.0,label:"Poor Scenting",     detail:"Pressure dropping — front approaching. Scent rising off the ground, dogs will struggle."};
  return          {trend:"FALLING FAST",       arrow:"↓",color:"#c0392b",scentRating:1.5,label:"Terrible Scenting", detail:"Pressure falling fast — storm incoming. Scent disperses high. Stay home."};
}

function calcHuntScore({temp_f,wind_mph,precip_in,humidity,cloudcover,pressureTrend}){
  const sb=pressureTrend?pressureTrend.scentRating/10:0.5;
  const factors=[[temp_f,28,58,2.0],[wind_mph,0,12,1.5],[precip_in,0,0.05,2.0],[humidity,45,72,1.0],[cloudcover,15,65,0.5]];
  let score=0,total=0;
  factors.forEach(([v,mn,mx,w])=>{
    total+=w;
    if(v>=mn&&v<=mx)score+=w;
    else score+=w*Math.max(0,1-(v<mn?mn-v:v-mx)/(mx-mn))*0.6;
  });
  return Math.round(((score/total)*0.60+sb*0.40)*100)/10;
}

function scoreVerdict(s){
  if(s>=8.5)return{label:"PRIME CONDITIONS",color:"#f5a623",bg:"rgba(245,166,35,0.12)"};
  if(s>=7.0)return{label:"GOOD HUNTING",    color:"#6abf69",bg:"rgba(106,191,105,0.12)"};
  if(s>=5.0)return{label:"FAIR CONDITIONS", color:"#f0c040",bg:"rgba(240,192,64,0.12)"};
  if(s>=3.0)return{label:"POOR CONDITIONS", color:"#e07020",bg:"rgba(224,112,32,0.12)"};
  return      {label:"STAY HOME",           color:"#c0392b",bg:"rgba(192,57,43,0.12)"};
}

function factorRating(v,mn,mx){
  if(v>=mn&&v<=mx)return"good";
  return(v<mn?mn-v:v-mx)/(mx-mn)<0.4?"ok":"bad";
}

function wmoIcon(c){
  if(c===0)return"☀️";if(c<=2)return"🌤️";if(c<=3)return"⛅";if(c<=48)return"🌫️";
  if(c<=57)return"🌦️";if(c<=67)return"🌧️";if(c<=77)return"❄️";return"⛈️";
}

async function fetchWeather(lat,lon){
  const p=new URLSearchParams({latitude:lat,longitude:lon,
    hourly:["temperature_2m","windspeed_10m","precipitation","relativehumidity_2m","surface_pressure","cloudcover","weathercode"].join(","),
    current_weather:true,temperature_unit:"fahrenheit",windspeed_unit:"mph",
    precipitation_unit:"inch",timezone:"auto",forecast_days:1,past_days:1});
  return(await fetch(`https://api.open-meteo.com/v1/forecast?${p}`)).json();
}

async function reverseGeocode(lat,lon){
  try{
    const d=await(await fetch(`https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lon}&format=json`)).json();
    const a=d.address||{};return a.county||a.city||a.town||a.village||`${lat.toFixed(2)},${lon.toFixed(2)}`;
  }catch{return`${lat.toFixed(2)},${lon.toFixed(2)}`;}
}

