// ─── AUTH ─────────────────────────────────────────────────────────────────────
function AuthScreen({mode,onAuth,setScreen,showToast}){
  const[name,setName]=useState("");const[email,setEmail]=useState("");
  const[password,setPassword]=useState("");const[busy,setBusy]=useState(false);
  const[error,setError]=useState(null);const[success,setSuccess]=useState(null);
  const isSU=mode==="signup";
  const handle=async()=>{
    if(!email||!password||(isSU&&!name)){setError("Please fill in all fields.");return;}
    if(password.length<6){setError("Password must be at least 6 characters.");return;}
    setBusy(true);setError(null);
    try{
      if(isSU){
        const r=await sb.signUp(email,password,name);
        if(r.error){setError(r.error.message||"Signup failed.");setBusy(false);return;}
        const l=await sb.signIn(email,password);
        if(l.error){setSuccess("Account created! Check your email to confirm, then sign in.");setBusy(false);return;}
        await sb.upsertSubscriber(l.access_token,l.user.id,email,"free");
        onAuth({token:l.access_token,user:l.user,subscriber:{plan:"free"}});
      }else{
        const r=await sb.signIn(email,password);
        if(r.error){setError(r.error.message||"Login failed.");setBusy(false);return;}
        const sub=await sb.getSubscriber(r.access_token,r.user.id);
        onAuth({token:r.access_token,user:r.user,subscriber:sub||{plan:"free"}});
      }
    }catch{setError("Connection error. Try again.");}
    setBusy(false);
  };
  return(
    <div className="auth-screen">
      <button className="auth-back" onClick={()=>setScreen("splash")}>← Back</button>
      <img src={`data:image/png;base64,${LOGO_B64}`} alt="RC" className="auth-logo"/>
      <div className="auth-title">{isSU?"Create Account":"Welcome Back"}</div>
      <div className="auth-sub">{isSU?"Join RabbitCast today":"Sign in to your RabbitCast account"}</div>
      <div className="auth-form">
        {isSU&&<input className="auth-input" placeholder="Full name" value={name} onChange={e=>setName(e.target.value)}/>}
        <input className="auth-input" type="email" placeholder="Email address" value={email} onChange={e=>setEmail(e.target.value)} onKeyDown={e=>e.key==="Enter"&&handle()}/>
        <input className="auth-input" type="password" placeholder="Password (min 6 characters)" value={password} onChange={e=>setPassword(e.target.value)} onKeyDown={e=>e.key==="Enter"&&handle()}/>
        {error&&<div className="auth-error">⚠️ {error}</div>}
        {success&&<div className="auth-success">✓ {success}</div>}
        <button className="auth-btn" onClick={handle} disabled={busy}>{busy?"Please wait…":isSU?"Create My Account":"Sign In"}</button>
      </div>
      <div className="auth-switch">
        {isSU?<>Already have an account? <span onClick={()=>setScreen("login")}>Sign in</span></>
             :<>Don't have an account? <span onClick={()=>setScreen("signup")}>Sign up free</span></>}
      </div>
    </div>
  );
}

