// ─── LOCATION PICKER ──────────────────────────────────────────────────────────
function LocationPicker({setScreen,loadWeather,showToast,currentName}){
  const[query,setQuery]=useState("");const[busy,setBusy]=useState(false);
  const search=async()=>{
    if(!query.trim())return;setBusy(true);
    try{
      const r=await fetch(`https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(query)}&format=json&limit=1&countrycodes=us`);
      const d=await r.json();
      if(!d.length){showToast("Location not found — try a ZIP or county");setBusy(false);return;}
      const{lat,lon,display_name}=d[0];
      const short=display_name.split(",").slice(0,2).join(",").trim();
      await loadWeather(parseFloat(lat),parseFloat(lon),short);
      showToast(`📍 Location set: ${short}`);setScreen("dashboard");
    }catch{showToast("Search failed — check connection");}
    setBusy(false);
  };
  const gps=()=>{
    if(!navigator.geolocation){showToast("GPS not available");return;}
    setBusy(true);
    navigator.geolocation.getCurrentPosition(async({coords:{latitude:lat,longitude:lon}})=>{
      const name=await reverseGeocode(lat,lon);
      await loadWeather(lat,lon,name);showToast(`📍 GPS: ${name}`);setScreen("dashboard");setBusy(false);
    },()=>{showToast("GPS failed — try typing");setBusy(false);});
  };
  return(
    <div className="loc-screen">
      <div className="scr-hdr">
        <button className="back-btn" onClick={()=>setScreen("dashboard")}>←</button>
        <div className="scr-title">Set Location</div>
      </div>
      <div style={{marginBottom:14,fontSize:11,color:"var(--crd)",lineHeight:1.7}}>
        Enter a ZIP, city, or county for live conditions at your hunting patch.
      </div>
      <div className="loc-input-row">
        <input className="loc-input" placeholder="ZIP or county — e.g. 27330" value={query}
          onChange={e=>setQuery(e.target.value)} onKeyDown={e=>e.key==="Enter"&&search()}/>
        <button className="loc-search-btn" onClick={search} disabled={busy}>{busy?"…":"🔍"}</button>
      </div>
      <button className="loc-gps-btn" onClick={gps} disabled={busy}>📡 Use My GPS Location</button>
      <div style={{fontSize:10,color:"var(--crd)",textAlign:"center",lineHeight:1.7}}>
        Currently: <strong style={{color:"var(--cr)"}}>{currentName}</strong><br/>Location is never stored.
      </div>
    </div>
  );
}

// ─── SCENT METER ─────────────────────────────────────────────────────────────
function ScentMeter({pressureAnalysis,currentPressure}){
  if(!pressureAnalysis)return null;
  const{trend,arrow,color,label,detail}=pressureAnalysis;
  const barPct=Math.min(100,Math.max(0,((currentPressure-970)/70)*100));
  return(
    <div className="scent-hero" style={{background:"linear-gradient(145deg,#121e13,#0d1a0e)",border:`1px solid ${color}44`}}>
      <div className="scent-header">
        <div>
          <div className="scent-eyebrow">🐕 Scent Conditions</div>
          <div className="scent-label" style={{color}}>{label}</div>
          <div className="scent-detail">{detail}</div>
        </div>
        <div style={{textAlign:"right"}}>
          <div className="scent-arrow" style={{color}}>{arrow}</div>
          <div className="scent-trend" style={{color}}>{trend}</div>
        </div>
      </div>
      <div className="pressure-row">
        <div><div className="pressure-val" style={{color}}>{Math.round(currentPressure)}</div>
          <div className="pressure-unit">hPa<br/>Pressure</div></div>
        <div className="pbar-wrap">
          <div className="pbar-track"><div className="pbar-fill" style={{width:`${barPct}%`,background:`linear-gradient(to right,#c0392b,${color})`}}/></div>
          <div className="pbar-labels"><span>970 Low</span><span>1013 Normal</span><span>1040 High</span></div>
        </div>
      </div>
    </div>
  );
}

// ─── DASHBOARD ────────────────────────────────────────────────────────────────
function Dashboard({setScreen,showToast,weather,loading,error,locName,coords,loadWeather,session,onSignOut,paymentStatus}){
  const[activeNav,setActiveNav]=useState("home");
  const plan=session?.subscriber?.plan||"free";
  const isPaying=plan==="pro"||plan==="day"||plan==="monthly"||plan==="yearly";

  const parsed=(()=>{
    if(!weather?.hourly)return{};
    const h=weather.hourly,now=new Date();
    const ts=new Date(now.getFullYear(),now.getMonth(),now.getDate());
    const te=new Date(ts.getTime()+86400000);
    const all=h.time.map((t,i)=>({
      time:t,dt:new Date(t),hour:new Date(t).getHours(),
      temp:h.temperature_2m[i],wind:h.windspeed_10m[i],precip:h.precipitation[i],
      humidity:h.relativehumidity_2m[i],pressure:h.surface_pressure[i],cloud:h.cloudcover[i],wmo:h.weathercode[i],
    }));
    const ph=all.filter(x=>x.dt<=now&&x.dt>=new Date(now.getTime()-6*3600000)).map(x=>x.pressure);
    const pa=analyzePressure(ph);
    const today=all.filter(x=>x.dt>=ts&&x.dt<te).map(x=>({
      ...x,score:calcHuntScore({temp_f:x.temp,wind_mph:x.wind,precip_in:x.precip,humidity:x.humidity,cloudcover:x.cloud,pressureTrend:pa}),
    }));
    const cur=today.find(x=>x.hour===now.getHours())||today[0];
    const best=today.reduce((b,x)=>(!b||x.score>b.score)?x:b,null);
    const score=cur?calcHuntScore({temp_f:cur.temp,wind_mph:cur.wind,precip_in:cur.precip,humidity:cur.humidity,cloudcover:cur.cloud,pressureTrend:pa}):null;
    const verdict=score?scoreVerdict(score):null;
    const conds=cur?[
      {icon:"🌡️",val:`${Math.round(cur.temp)}°F`,lbl:"Temperature",rating:factorRating(cur.temp,28,58),note:cur.temp<28?"Too Cold":cur.temp>58?"Too Warm":"Ideal"},
      {icon:"💨",val:`${Math.round(cur.wind)} mph`,lbl:"Wind Speed",rating:factorRating(cur.wind,0,12),note:cur.wind>12?"Too Windy":"Ideal"},
      {icon:"💧",val:`${Math.round(cur.humidity)}%`,lbl:"Humidity",rating:factorRating(cur.humidity,45,72),note:cur.humidity<45?"Dry":cur.humidity>72?"Muggy":"Ideal"},
      {icon:"🌧️",val:`${cur.precip.toFixed(2)}"`,lbl:"Precip",rating:factorRating(cur.precip,0,0.05),note:cur.precip>0.05?"Rain":"Clear"},
      {icon:"☁️",val:`${Math.round(cur.cloud)}%`,lbl:"Cloud Cover",rating:factorRating(cur.cloud,15,65),note:cur.cloud<15?"Clear":cur.cloud>65?"Overcast":"Partial"},
    ]:[];
    const tip=(()=>{
      if(!cur||!pa)return"Loading…";
      const m=[pa.detail];
      if(cur.temp<28)m.push("Temps below freezing — try mid-morning.");
      else if(cur.temp>60)m.push("It's warm — work shaded creek bottoms.");
      if(cur.precip>0.1)m.push("Rain washes scent. Hunt downwind of cover.");
      if(best)m.push(`Best window: ${new Date(best.time).toLocaleTimeString([],{hour:"numeric",minute:"2-digit"})} (score: ${best.score.toFixed(1)}).`);
      return m.join(" ");
    })();
    return{today,cur,pa,score,verdict,conds,best,tip};
  })();

  const{today,cur,pa,score,verdict,conds,best,tip}=parsed;
  const fmtHr=t=>new Date(t).toLocaleTimeString([],{hour:"numeric"});

  return(
    <div>
      <div className="dash-hdr">
        <img src={`data:image/png;base64,${LOGO_B64}`} alt="RC" className="dash-logo"/>
        <div className="dash-brand">RabbitCast</div>
        <div className="dash-user" onClick={session?onSignOut:()=>setScreen("login")}>
          {session
            ?<><div style={{fontSize:10,color:"var(--cr)"}}>{session.user?.email?.split("@")[0]} · {isPaying?"Pro ✦":"Free"}</div><div className="dash-signout">Tap to sign out</div></>
            :<><div style={{fontSize:10,color:"var(--amb)"}}>Sign In</div><div style={{fontSize:9,color:"var(--crd)"}}>or create account</div></>
          }
        </div>
      </div>

      <div className="loc-bar" onClick={()=>setScreen("location")}>
        <span style={{fontSize:16}}>📍</span>
        <div className="loc-text"><strong>{locName}</strong>Tap to change location</div>
        <span className="loc-change">Change</span>
      </div>

      {/* Payment success message */}
      {paymentStatus==="success"&&(
        <div className="success-banner">
          <h3>🎉 You're a Pro Hunter!</h3>
          <p>Payment confirmed. Full access is now unlocked. Go load the truck.</p>
        </div>
      )}

      {loading&&<div className="loading"><div className="spinner"/><div style={{fontSize:11,color:"var(--crd)"}}>Fetching live conditions…</div></div>}
      {error&&!loading&&(
        <div className="error-box">⚠️ {error}<br/>
          <button style={{marginTop:8,background:"var(--amb)",border:"none",borderRadius:4,padding:"7px 14px",color:"var(--bg)",cursor:"pointer",fontWeight:700,fontSize:11}}
            onClick={()=>loadWeather(coords.lat,coords.lon,locName)}>Retry</button>
        </div>
      )}

      {!loading&&!error&&score!==null&&(
        <>
          <div className="score-hero">
            <div className="s-lbl">Today's Hunt Score</div>
            <div className="s-num">{score?.toFixed(1)}</div>
            <div className="s-sub">out of 10 · {locName}</div>
            <div className="s-verdict" style={{color:verdict?.color,borderColor:verdict?.color,background:verdict?.bg}}>{verdict?.label}</div>
          </div>

          {!isPaying&&(
            <div className="lock-gate">
              <div className="lock-top">
                <div className="lock-icon">🔒</div>
                <div className="lock-title">Unlock Full Forecast</div>
                <div className="lock-sub">Upgrade to see what's driving today's score and exactly when to load the truck.</div>
                <ul className="lock-features">
                  <li>Scent Meter &amp; barometric pressure trend</li>
                  <li>Hourly hunt score breakdown</li>
                  <li>Wind, humidity &amp; rain conditions</li>
                  <li>AI Field Advisor tip for today</li>
                  <li>Save your favorite hunting spots</li>
                </ul>
              </div>
              <button className="lock-btn" onClick={()=>setScreen("pricing")}>View Plans — Starting at $5.99 →</button>
            </div>
          )}

          {isPaying&&(
            <>
              <ScentMeter pressureAnalysis={pa} currentPressure={cur?.pressure}/>
              <div className="sec-title">Conditions Detail</div>
              <div className="cond-grid">
                {conds.map((c,i)=>(
                  <div key={i} className="cond-card">
                    <div className="c-icon">{c.icon}</div>
                    <div className="c-val">{c.val}</div>
                    <div className="c-lbl">{c.lbl}</div>
                    <div className={`c-rating ${c.rating}`}>{c.note}</div>
                  </div>
                ))}
              </div>
              <div className="sec-title">Hourly Breakdown</div>
              <div className="hourly-row">
                {(today||[]).map((h,i)=>(
                  <div key={i} className={`hr-card ${h===best?"best":""}`}>
                    <div className="hr-time">{fmtHr(h.time)}</div>
                    <div className="hr-score">{h.score.toFixed(1)}</div>
                    <div className="hr-icon">{wmoIcon(h.wmo)}</div>
                    <div className="hr-pres">{Math.round(h.pressure)}</div>
                  </div>
                ))}
              </div>
              <div className="sec-title">Field Advisor Tip</div>
              <div className="tip-box">
                <div style={{fontSize:20,flexShrink:0,marginTop:2}}>🐕</div>
                <div><div className="tip-t">Today's Tip</div><div className="tip-p">{tip}</div></div>
              </div>
            </>
          )}
        </>
      )}

      <div className="bot-nav">
        {[{id:"home",icon:"🏠",lbl:"Home"},{id:"forecast",icon:"📅",lbl:"Forecast"},
          {id:"spots",icon:"📍",lbl:"Spots"},{id:"advisor",icon:"🐕",lbl:"Advisor"}].map(n=>(
          <button key={n.id} className={`nav-btn ${activeNav===n.id?"active":""}`}
            onClick={()=>{setActiveNav(n.id);if(n.id!=="home")showToast(`${n.lbl} — coming soon!`);}}>
            <span className="nav-icon">{n.icon}</span><span className="nav-lbl">{n.lbl}</span>
          </button>
        ))}
      </div>
    </div>
  );
}
